import {
  useState
} from "react";

import axios from "axios";

import ReactMarkdown from "react-markdown";

import { Prism as SyntaxHighlighter }
from "react-syntax-highlighter";

import { oneDark }
from "react-syntax-highlighter/dist/esm/styles/prism";

function App() {

  /* =========================
     STATES
  ========================= */

  const [conversations,
    setConversations] =
    useState([]);

  const [currentChatId,
    setCurrentChatId] =
    useState(null);

  const [message,
    setMessage] =
    useState("");

  const [loading,
    setLoading] =
    useState(false);

  /* =========================
     CREATE NEW CHAT
  ========================= */

  const createNewChat =
    () => {

      const newChat = {

        id: Date.now(),

        title: "New Chat",

        messages: []
      };

      setConversations([
        newChat,
        ...conversations
      ]);

      setCurrentChatId(
        newChat.id
      );
    };

  /* =========================
     CURRENT CHAT
  ========================= */

  const currentChat =
    conversations.find(
      (chat) =>
        chat.id ===
        currentChatId
    );

  /* =========================
     SEND MESSAGE
  ========================= */

  const sendMessage =
    async () => {

      if (!message.trim())
        return;

      let activeChatId =
        currentChatId;

      let updatedChats =
        [...conversations];

      /* CREATE CHAT */

      if (!activeChatId) {

        const newChat = {

          id: Date.now(),

          title: message,

          messages: []
        };

        updatedChats = [
          newChat,
          ...updatedChats
        ];

        activeChatId =
          newChat.id;

        setCurrentChatId(
          activeChatId
        );
      }

      /* USER MESSAGE */

      const userMessage = {

        role: "user",

        text: message
      };

      updatedChats =
        updatedChats.map(
          (chat) => {

            if (
              chat.id ===
              activeChatId
            ) {

              return {

                ...chat,

                title:
                  chat.messages
                    .length === 0
                    ? message
                    : chat.title,

                messages: [
                  ...chat.messages,
                  userMessage
                ]
              };
            }

            return chat;
          }
        );

      setConversations(
        updatedChats
      );

      const currentMessage =
        message;

      setMessage("");

      setLoading(true);

      try {

        /* API CALL */

        const res =
          await axios.post(
            "http://127.0.0.1:8000/api/chat",

            {
              message:
                currentMessage
            }
          );

        const aiMessage = {

          role: "ai",

          text:
            res.data.response
        };

        updatedChats =
          updatedChats.map(
            (chat) => {

              if (
                chat.id ===
                activeChatId
              ) {

                return {

                  ...chat,

                  messages: [
                    ...chat.messages,
                    aiMessage
                  ]
                };
              }

              return chat;
            }
          );

        setConversations(
          updatedChats
        );

      } catch (error) {

        console.log(error);

        const errorMessage = {

          role: "ai",

          text:
            "Backend connection error"
        };

        updatedChats =
          updatedChats.map(
            (chat) => {

              if (
                chat.id ===
                activeChatId
              ) {

                return {

                  ...chat,

                  messages: [
                    ...chat.messages,
                    errorMessage
                  ]
                };
              }

              return chat;
            }
          );

        setConversations(
          updatedChats
        );
      }

      setLoading(false);
    };

  /* =========================
     DELETE CHAT
  ========================= */

  const deleteChat =
    (id) => {

      const filteredChats =
        conversations.filter(
          (chat) =>
            chat.id !== id
        );

      setConversations(
        filteredChats
      );

      if (
        filteredChats.length > 0
      ) {

        setCurrentChatId(
          filteredChats[0].id
        );

      } else {

        setCurrentChatId(null);
      }
    };

  /* =========================
     UI
  ========================= */

  return (

    <div className="flex h-screen bg-slate-950 text-white overflow-hidden">

      {/* SIDEBAR */}

      <div className="w-72 bg-slate-900 border-r border-slate-800 p-5 flex flex-col">

        <h1 className="text-2xl font-bold text-cyan-400 mb-8">

          AI College Companion

        </h1>

        <button
          onClick={
            createNewChat
          }

          className="w-full bg-cyan-500 hover:bg-cyan-600 p-3 rounded-xl font-semibold transition"
        >

          + New Chat

        </button>

        {/* CHAT HISTORY */}

        <div className="mt-8 overflow-y-auto space-y-3 flex-1">

          {
            conversations.map(
              (chat) => (

                <div
                  key={chat.id}

                  className={`p-3 rounded-xl flex items-center justify-between cursor-pointer transition ${
                    currentChatId ===
                    chat.id

                      ? "bg-cyan-500"

                      : "bg-slate-800 hover:bg-slate-700"
                  }`}
                >

                  <div
                    className="truncate flex-1"

                    onClick={() =>
                      setCurrentChatId(
                        chat.id
                      )
                    }
                  >

                    {chat.title}

                  </div>

                  <button
                    onClick={() =>
                      deleteChat(
                        chat.id
                      )
                    }

                    className="ml-2 text-red-300 hover:text-red-500"
                  >

                    ✕

                  </button>

                </div>
              ))
          }

        </div>

      </div>

      {/* MAIN */}

      <div className="flex-1 flex flex-col">

        {/* HEADER */}

        <div className="p-5 border-b border-slate-800 text-2xl font-semibold text-cyan-300">

          AI Assistant

        </div>

        {/* CHAT */}

        <div className="flex-1 overflow-y-auto p-6 space-y-6">

          {
            currentChat?.messages.map(
              (
                chat,
                index
              ) => (

                <div
                  key={index}

                  className={`max-w-4xl p-5 rounded-2xl whitespace-pre-wrap leading-8 shadow-lg ${
                    chat.role ===
                    "user"

                      ? "bg-cyan-500 ml-auto text-white"

                      : "bg-slate-800 text-gray-200"
                  }`}
                >

                  {
                    chat.role ===
                    "ai"

                      ? (

                        <ReactMarkdown

                          components={{

                            code({

                              inline,

                              className,

                              children,

                              ...props

                            }) {

                              const match =
                                /language-(\w+)/.exec(
                                  className || ""
                                );

                              return !inline &&
                                match ? (

                                <SyntaxHighlighter
                                  style={oneDark}

                                  language={
                                    match[1]
                                  }

                                  PreTag="div"

                                  {...props}
                                >

                                  {String(
                                    children
                                  ).replace(
                                    /\n$/,
                                    ""
                                  )}

                                </SyntaxHighlighter>

                              ) : (

                                <code
                                  className="bg-slate-700 px-1 py-0.5 rounded"

                                  {...props}
                                >

                                  {children}

                                </code>
                              );
                            }
                          }}
                        >

                          {chat.text}

                        </ReactMarkdown>

                      ) : (

                        chat.text
                      )
                  }

                </div>
              ))
          }

          {/* LOADING */}

          {
            loading && (

              <div className="bg-slate-800 p-4 rounded-2xl w-fit">

                Thinking...

              </div>
            )
          }

        </div>

        {/* INPUT */}

        <div className="p-5 border-t border-slate-800 flex gap-4 items-center bg-slate-950">

          <input
            type="text"

            placeholder="Ask anything..."

            value={message}

            onChange={(e) =>
              setMessage(
                e.target.value
              )
            }

            onKeyDown={(e) => {

              if (
                e.key === "Enter"
              ) {

                sendMessage();
              }
            }}

            className="flex-1 p-4 rounded-xl bg-slate-800 border border-slate-700 focus:outline-none focus:ring-2 focus:ring-cyan-500"
          />

          {/* SEND */}

          <button
            onClick={
              sendMessage
            }

            className="bg-cyan-500 hover:bg-cyan-600 px-6 py-4 rounded-xl font-semibold transition"
          >

            Send

          </button>

        </div>

      </div>

    </div>
  );
}

export default App;
